import java.util.*;

class Solution {
    int[][] memo;
    private int dp(int i, int j, int[] cuts) {
        if (j - i <= 1) return 0;
        if (memo[i][j] != -1) return memo[i][j];
        int ans = Integer.MAX_VALUE;
        int cost = cuts[j] - cuts[i];
        for (int k = i + 1; k < j; k++) {
            ans = Math.min(ans, cost + dp(i, k, cuts) + dp(k, j, cuts));
        }
        return memo[i][j] = ans;
    }
    public int minCost(int n, int[] cuts) {
        int m = cuts.length;
        int[] all = new int[m + 2];
        all[0] = 0;
        for (int i = 0; i < m; i++) all[i + 1] = cuts[i];
        all[m + 1] = n;
        Arrays.sort(all);
        memo = new int[all.length][all.length];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dp(0, all.length - 1, all);
    }
}

var minCost = function(n, cuts) {
    const all = [0, ...cuts, n].sort((a, b) => a - b);
    const m = all.length;
    const memo = Array.from({ length: m }, () => new Array(m).fill(-1));
    function dp(i, j) {
        if (j - i <= 1) return 0;
        if (memo[i][j] !== -1) return memo[i][j];
        let ans = Infinity;
        const cost = all[j] - all[i];
        for (let k = i + 1; k < j; k++) {
            ans = Math.min(ans, cost + dp(i, k) + dp(k, j));
        }
        return memo[i][j] = ans;
    }
    return dp(0, m - 1);
};
